package com.rk.fooddelivery.payment.service; import com.rk.fooddelivery.order.entity.PaymentStatus; import com.rk.fooddelivery.order.repository.OrderRepository; import com.rk.fooddelivery.order.service.StockReservationService; import com.rk.fooddelivery.payment.repository.PaymentRepository; import java.time.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class PaymentExpiryJob { private final OrderRepository orders; private final PaymentRepository payments; private final StockReservationService stock; private final Clock clock; public PaymentExpiryJob(OrderRepository orders,PaymentRepository payments,StockReservationService stock,Clock clock){this.orders=orders;this.payments=payments;this.stock=stock;this.clock=clock;} @Scheduled(fixedDelayString="${payment.expiry.poll-ms:30000}") @Transactional public void expire(){orders.findAll().stream().filter(o->o.paymentStatus()==PaymentStatus.PENDING&&o.getPaymentDeadlineAt()!=null&&o.getPaymentDeadlineAt().isBefore(clock.instant())).forEach(o->{o.payment(PaymentStatus.FAILED);payments.findFirstByOrderIdOrderByIdDesc(o.getId()).ifPresent(p->p.fail("expired"));stock.releaseOnce(o.getId());});} }
